-- P6-C workshop-side people (synthetic): staff for every workshop role plus customers.
-- Safe to re-run: inserts new rows and updates existing ones. It never deletes anything.
SET NAMES utf8mb4;
ON DUPLICATE KEY UPDATE `email`=VALUES(`email`),`password_hash`=VALUES(`password_hash`),`full_name`=VALUES(`full_name`),`role`=VALUES(`role`),`phone`=VALUES(`phone`),`contact_preference`=VALUES(`contact_preference`),`store_code`=VALUES(`store_code`),`student_code`=VALUES(`student_code`),`specialty`=VALUES(`specialty`),`preferred_language`=VALUES(`preferred_language`),`is_synthetic`=VALUES(`is_synthetic`),`is_active`=VALUES(`is_active`),`is_archived`=VALUES(`is_archived`),`created_at`=VALUES(`created_at`),`updated_at`=VALUES(`updated_at`);
